import * as React from "react";
import * as stylex from "@stylexjs/stylex";
import { raster } from "./tokens.stylex";
import { rs } from "./rs";

export interface InputOTPProps extends Omit<React.HTMLAttributes<HTMLDivElement>, "onChange"> {
  length?: number;
  onChange?: (code: string) => void;
  /** Called once every cell is filled. */
  onComplete?: (code: string) => void;
  "aria-label"?: string;
}

const styles = stylex.create({
  otp: {
    display: "flex",
    gap: 8,
    width: {
      default: null,
      ["@media (max-width: 640px)"]: "100%",
    },
  },
  cell: {
    width: {
      default: 40,
      ["@media (max-width: 640px)"]: "auto",
    },
    flexGrow: {
      default: null,
      ["@media (max-width: 640px)"]: 1,
    },
    minWidth: {
      default: null,
      ["@media (max-width: 640px)"]: 0,
    },
    height: {
      default: 48,
      ["@media (max-width: 640px)"]: raster.hit,
    },
    minHeight: {
      default: null,
      ["@media (max-width: 640px)"]: raster.hit,
    },
    textAlign: "center",
    fontSize: 18,
    fontWeight: 600,
    fontVariantNumeric: "tabular-nums",
    appearance: "none",
    WebkitAppearance: "none",
    color: "var(--text)",
    caretColor: "var(--text)",
    backgroundColor: "var(--bg)",
    borderWidth: raster.hairline,
    borderStyle: "solid",
    borderColor: {
      default: raster.divider,
      ":focus": raster.accent,
    },
    borderRadius: {
      default: raster.radiusSm,
      ["@media (max-width: 640px)"]: 0,
    },
    outline: "none",
    fontFamily: "inherit",
    padding: 0,
    ":-webkit-autofill": {
      WebkitTextFillColor: "var(--text)",
      caretColor: "var(--text)",
      backgroundColor: "var(--bg)",
      boxShadow: "inset 0 0 0 1000px var(--bg)",
    },
  },
});

/** One cell per character. Auto-advance, backspace, paste. */
export function InputOTP({
  length = 6,
  onChange,
  onComplete,
  className,
  style,
  "aria-label": ariaLabel = "One-time code",
  ...props
}: InputOTPProps) {
  const [chars, setChars] = React.useState<string[]>(() => Array(length).fill(""));
  const refs = React.useRef<Array<HTMLInputElement | null>>([]);

  const commit = (next: string[]) => {
    setChars(next);
    const code = next.join("");
    onChange?.(code);
    if (code.length === length) onComplete?.(code);
  };

  const setAt = (index: number, value: string) => {
    const next = [...chars];
    next[index] = value;
    commit(next);
  };

  const paste = (index: number, text: string) => {
    const clean = text.replace(/\D/g, "").slice(0, length - index);
    if (!clean) return;
    const next = [...chars];
    for (let i = 0; i < clean.length; i++) next[index + i] = clean[i]!;
    commit(next);
    refs.current[Math.min(index + clean.length, length - 1)]?.focus();
  };

  const sx = rs(["rs-otp", className], styles.otp);
  const cell = rs([], styles.cell);

  return (
    <div className={sx.className} style={{ ...sx.style, ...style }} role="group" aria-label={ariaLabel} {...props}>
      {chars.map((char, index) => (
        <input
          key={index}
          ref={(el) => {
            refs.current[index] = el;
          }}
          inputMode="numeric"
          autoComplete={index === 0 ? "one-time-code" : "off"}
          maxLength={1}
          value={char}
          aria-label={`Digit ${index + 1}`}
          className={cell.className}
          style={cell.style}
          onChange={(e) => {
            const value = e.target.value.replace(/\D/g, "");
            if (value.length > 1) {
              paste(index, value);
              return;
            }
            setAt(index, value);
            if (value) refs.current[index + 1]?.focus();
          }}
          onKeyDown={(e) => {
            if (e.key === "Backspace" && !chars[index] && index > 0) {
              refs.current[index - 1]?.focus();
              setAt(index - 1, "");
            }
            if (e.key === "ArrowLeft") refs.current[index - 1]?.focus();
            if (e.key === "ArrowRight") refs.current[index + 1]?.focus();
          }}
          onPaste={(e) => {
            e.preventDefault();
            paste(index, e.clipboardData.getData("text"));
          }}
        />
      ))}
    </div>
  );
}

import * as stylex from "@stylexjs/stylex";

/**
 * StyleX vars alias Raster CSS custom properties. Not a second scale.
 * Values live in packages/core/css/tokens.css (generated from src/tokens.ts).
 */
export const raster = stylex.defineVars({
  paper: "var(--bg)",
  ink: "var(--text)",
  gray: "var(--text-secondary)",
  accent: "var(--accent)",
  divider: "var(--divider)",
  dividerSubtle: "var(--divider-subtle)",
  tableAlt: "var(--table-alt)",
  gridLine: "var(--grid-line)",
  radiusSm: "var(--radius-sm)",
  radius: "var(--radius)",
  radiusChrome: "var(--radius-chrome)",
  radiusIn: "var(--radius-in)",
  pad: "var(--pad)",
  gutter: "var(--gutter)",
  module: "var(--grid-size)",
  gridImage: "var(--grid-image)",
  gridPos: "var(--grid-pos)",
  hit: "var(--hit)",
  controlH: "var(--control-h)",
  controlFs: "var(--control-fs)",
  controlLabel: "var(--control-label)",
  durationSnap: "var(--duration-snap)",
  duration: "var(--duration)",
  durationConfirm: "var(--duration-confirm)",
  ease: "var(--ease)",
  transition: "var(--transition)",
  textScale: "var(--text-scale)",
  hairline: "1px",
});

/** Inter stack. Same as body in base.css. Not a token var — @font-face stays CSS. */
export const rasterFont =
  "Inter, -apple-system, BlinkMacSystemFont, 'Segoe UI', system-ui, sans-serif";

export const rasterMono = "ui-monospace, SFMono-Regular, Menlo, monospace";

/** Compile-time media keys. StyleX only folds defineConsts, not plain strings. */
export const mq = stylex.defineConsts({
  phone: "@media (max-width: 640px)",
  mobileGrid: "@media (max-width: 480px)",
  at900: "@media (min-width: 900px)",
  at899: "@media (max-width: 899px)",
  rail: "@media (min-width: 1024px)",
  wide: "@media (min-width: 1440px)",
  reduce: "@media (prefers-reduced-motion: reduce)",
  touch: "@media (hover: none)",
});

/** Phone recut (≤640). Desktop stays the poster. */
export const phone = mq.phone;

/** Mobile grid (≤480). */
export const mobileGrid = mq.mobileGrid;

/** Catalog rail. */
export const rail = mq.rail;

/** Wide catalog. */
export const wide = mq.wide;

import type { CSSProperties } from "react";
import * as stylex from "@stylexjs/stylex";
import { cx } from "./cx";

type StyleXProps = { className?: string; style?: CSSProperties };

/** Merge Raster class names with StyleX props. CSS-first classes stay on the node. */
export function rs(classNames: Array<string | false | null | undefined>, ...styles: unknown[]): StyleXProps {
  const sx = (stylex.props as (...args: unknown[]) => StyleXProps)(...styles);
  return {
    className: cx(...classNames, sx.className),
    style: sx.style,
  };
}

/** Join class names, dropping falsy parts. */
export function cx(...parts: Array<string | false | null | undefined>): string {
  return parts.filter(Boolean).join(" ");
}
